import React from 'react'
import PropTypes from 'prop-types'
import { Row, Col, Button, Spin, Card, notification } from 'antd'
import { connect } from 'react-redux'
import EditValidationStyleWrapper from './index.style'
// import { localStorageCheck } from '../../../../../util/localstorageCheck'
import DataValidationFieldWrapper from '../../components/DataValidation'
import dataValidationActions from '../../../../../../../redux/productConfig/actions'
import { get } from 'lodash'
import { traceValidation } from '../commanFunction'
import PageHeadWrapper from '../../../../../components/pageHeadWrapper'
import { StateProvider } from '../../components/DataValidation/store'
import QuerySearchBuilder from '../../../../../../../../helpers/querySearchBuilder'

const {
  resetProductConfigRedux,
  getAllProductValidations,
  editProductAttributes
} = dataValidationActions
class EditDataValidation extends React.Component {
  state = {
    productAttributes: [],
    validationData: [],
    intialData: [],
    packageCode: '',
    step1Data: {}
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      productValidation,
      productValidationMesage,
      editProductValidationsMessage,
      editProductValidationsData
    } = nextProps

    if (productValidationMesage === 'success') {
      this.setState({
        validationData: get(productValidation, 'data.details', [])
      })
      // this.props.resetProductConfigRedux([ 'getAllProductValidationMessage' ])
    }
    if (editProductValidationsMessage === 'success') {
      const productCode = get(this.state.step1Data, 'code', '')
      notification.success(
        { message: get(editProductValidationsData, 'message') }
      )
      this.props.resetProductConfigRedux(['editProductValidationsMessage'])
      const queryString = QuerySearchBuilder({ product_code: productCode })

      this.props.history.push({
        pathname: '/product-config/detail',
        search: queryString,
        state: {
          code: productCode,
          visible: '2',
          packageCode: this.state.packageCode
        }
      })
    }
    if (editProductValidationsMessage !== 'success' && editProductValidationsMessage !== undefined) {
      notification.error(
        { message: 'Failed to Edit Package Validation' }
      )
      this.props.resetProductConfigRedux(['editProductValidationsMessage'])
    }
  }

  componentDidMount () {
    const { location, match } = this.props
    const formName = get(location, 'state.formName', '')
    switch (formName) {
      case 'modal-page-validation':
      case 'detail-page-validation': {
        const formData = get(location, 'state.formData', '')
        this.setState({
          intialData: get(formData, 'initialData', []),
          packageCode: get(match, 'params.id', ''),
          productAttributes: get(formData, 'step2Data', []),
          step1Data: get(formData, 'step1Data', {})
        })
        this.props.getAllProductValidations()
      }
        break
      default: {
        this.props.history.goBack()
      }
    }
  }

  handleOnCancelEditHandler = () => {
    this.props.history.goBack()
  }

  handleSubmitValidationDataHandler = () => {
    const { productAttributes, step1Data, packageCode } = this.state
    const validations = traceValidation(productAttributes).data
    const productCode = step1Data
    this.props.editProductAttributes({
      query: {
        productCode: get(productCode, 'code'),
        packageCode: packageCode
      },
      body: validations
    })
  }

  componentWillUnmount () {
    const { productAttributes } = this.state
    productAttributes.forEach(item => {
      window.sessionStorage.removeItem(`${item.code}-${item.id}`)
    })
    window.sessionStorage.removeItem('formData')
  }

  render () {
    const { editProductValidationsLoading, editProductValidationError } = this.props
    const { productAttributes, validationData, intialData, packageCode } = this.state
    const policyCreationData = productAttributes.length > 0 ? productAttributes.filter(item => item.attribute_type === 'creation') : []
    const endorsementCreationData = productAttributes.length > 0 ? productAttributes.filter(item => item.attribute_type !== 'creation') : []
    return (
      <EditValidationStyleWrapper>
        <PageHeadWrapper
          heading={`Editing data validation for package: ${packageCode}`}
        >
          {
            (validationData.length > 0 && productAttributes.length > 0) &&
              <Spin spinning={editProductValidationsLoading && !editProductValidationError} tip='Loading....'>
                <Card className='edit-card'>
                  <p><b>Product Validation</b></p>
                  <StateProvider>
                    <DataValidationFieldWrapper
                      attributesData={policyCreationData}
                      productAttributes={policyCreationData}
                      validationData={validationData}
                      intialData={intialData}
                      packageName={packageCode}
                    />
                  </StateProvider>
                </Card>

                <Card className='edit-card lower'>
                  <p><b>Endorsement Validation</b></p>
                  <StateProvider>
                    <DataValidationFieldWrapper
                      attributesData={productAttributes}
                      productAttributes={endorsementCreationData}
                      validationData={validationData}
                      intialData={intialData}
                      packageName=''
                    />
                  </StateProvider>
                </Card>

                <Row type='flex' justify='center' gutter={30} className='button-div'>
                  <Col>
                    <Button onClick={this.handleOnCancelEditHandler}>Cancel</Button>
                  </Col>
                  <Col>
                    <Button
                      type='primary'
                      onClick={this.handleSubmitValidationDataHandler}
                    >
                      Submit
                    </Button>
                  </Col>
                </Row>
              </Spin>
          }
        </PageHeadWrapper>
      </EditValidationStyleWrapper>
    )
  }
}
EditDataValidation.defaultProps = {
  editProductValidationsLoading: false,
  editProductValidationError: false
}
EditDataValidation.propTypes = {
  editProductValidationsLoading: PropTypes.bool,
  editProductValidationError: PropTypes.bool
}
export default connect(
  state => ({
    editProductValidationsMessage: state.ProductConfigurable.editProductValidationsMessage,
    editProductValidationsData: state.ProductConfigurable.editProductValidationsData,
    editProductValidationsLoading: state.Loading.EDIT_PRODUCT_ATTRIBUTES,
    editProductValidationError: state.Error.EDIT_PRODUCT_ATTRIBUTES,
    productValidation: state.ProductConfigurable.getAllProductValidation,
    productValidationMesage: state.ProductConfigurable.getAllProductValidationMessage
  }), {
    editProductAttributes,
    resetProductConfigRedux,
    getAllProductValidations
  }
)(EditDataValidation)
